package com.itematlas;

import com.itematlas.config.DefaultOpenSources;
import com.itematlas.config.DefaultOpenUses;
import com.itematlas.config.MenuLookupMode;
import java.util.Collections;
import java.util.Set;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(ItemAtlasConfig.GROUP)
public interface ItemAtlasConfig extends Config
{
	String GROUP = "itematlas";

	@ConfigItem(
		keyName = "invLookupMode",
		name = "Inventory Lookup",
		description = "Whether to show an Atlas Lookup option on inventory items, and when",
		position = 0
	)
	default MenuLookupMode invLookupMode()
	{
		return MenuLookupMode.RIGHT;
	}

	@ConfigItem(
		keyName = "equipLookupMode",
		name = "Equipment Lookup",
		description = "Whether to show an Atlas Lookup option on equipped items, and when",
		position = 1
	)
	default MenuLookupMode equipLookupMode() {
		return MenuLookupMode.RIGHT;
	}

	@ConfigItem(
		keyName = "bankLookupMode",
		name = "Bank Lookup",
		description = "Whether to show an Atlas Lookup option on bank items, and when",
		position = 2
	)
	default MenuLookupMode bankLookupMode()
	{
		return MenuLookupMode.RIGHT;
	}

	@ConfigItem(
		keyName = "clogLookupMode",
		name = "CLog Lookup",
		description = "Whether to show an Atlas Lookup option on collection log items, and when",
		position = 3
	)
	default MenuLookupMode clogLookupMode() {
		return MenuLookupMode.RIGHT;
	}

	@ConfigItem(
		keyName = "ccBroadcastLookup",
		name = "Chat Broadcast Lookups",
		description = "Whether to show an Atlas Lookup option on clan chat loot drop broadcasts",
		position = 4
	)
	default boolean ccBroadcastLookup() {
		return true;
	}

	@ConfigItem(
		keyName = "defaultOpenSources",
		name = "Default Open Sources",
		description = "Which 'Sources' categories to open by default",
		position = 5
	)
	default Set<DefaultOpenSources> defaultOpenSources() {
		return Collections.emptySet();
	}

	@ConfigItem(
		keyName = "defaultOpenUses",
		name = "Default Open Uses",
		description = "Which 'Uses' categories to open by default",
		position = 6
	)
	default Set<DefaultOpenUses> defaultOpenUses() {
		return Collections.emptySet();
	}

	@ConfigItem(
		keyName = "showMembersStar",
		name = "Members star",
		description = "Mark members-only shops, spawns and drop locations with a star",
		position = 7
	)
	default boolean showMembersStar()
	{
		return false;
	}

	@ConfigSection(
		name = "Integrations",
		description = "Integrations with other Plugins",
		position = 8
	)
	String integrationSection = "integrationSection";

	@ConfigItem(
		keyName = "routeShopSources",
		name = "Route shops",
		description = "Include listed shops when routing to an item source",
		position = 9,
		section = integrationSection
	)
	default boolean routeShopSources()
	{
		return true;
	}

	@ConfigItem(
		keyName = "routeGroundSpawnSources",
		name = "Route ground spawns",
		description = "Include listed ground spawns when routing to an item source",
		position = 10,
		section = integrationSection
	)
	default boolean routeGroundSpawnSources()
	{
		return true;
	}

	@ConfigItem(
		keyName = "routeDropSources",
		name = "Route drop sources",
		description = "Include the locations of monsters and objects that drop the item when routing to an item source",
		position = 11,
		section = integrationSection
	)
	default boolean routeDropSources()
	{
		return true;
	}

	@ConfigItem(
		keyName = "routeBestDropRate",
		name = "Route best drop rate",
		description = "When routing to drop sources, only consider the monsters and objects with the best drop rate instead of every one",
		position = 12,
		section = integrationSection
	)
	default boolean routeBestDropRate()
	{
		return false;
	}

	@ConfigItem(
		keyName = "bmeNPCLookup",
		name = "Better Monster Examine",
		description = "Click NPCs in the Drops section to look them up in Better Monster Examine. This requires the Better Monster Examine plugin to be installed and enabled",
		position = 13,
		section = integrationSection
	)
	default boolean bmeNPCLookup()
	{
		return true;
	}

}

package com.itematlas;

import com.google.common.collect.ImmutableMap;
import com.google.gson.Gson;
import com.google.inject.Provides;
import com.itematlas.config.MenuLookupMode;
import com.itematlas.db.H2DataProvider;
import com.itematlas.ui.AtlasDropsPanel;
import com.itematlas.ui.AtlasPanel;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Item Atlas",
	internalName = "item-atlas",
	description = "Shows wiki-sourced information where items can be found and what they're used for",
	tags = {"item", "sources", "uses", "recipe", "crafting", "shops", "drops", "spawns", "wiki", "gps", "route"}
)
public class ItemAtlasPlugin extends Plugin
{

	@Inject
	private Client client;

	@Inject
	private ItemAtlasConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Gson gson;

	@Inject
	private H2DataProvider dataProvider;

	@Inject
	private ItemOwnership itemOwnership;

	@Getter(AccessLevel.PACKAGE)
	private NavigationButton navButton;

	@Getter(AccessLevel.PACKAGE)
	@Setter(AccessLevel.PACKAGE)
	private AtlasPanel atlasPanel;

	// Items with different collection log IDs that are not mapped by Enum 3721
	private static final Map<Integer, Integer> ITEM_ID_MAP = new ImmutableMap.Builder<Integer, Integer>()
		.put(25615, 21539) // Large water container
		.build();

	public static final int SCRIPT_REBUILD_CHATBOX = 84;
	public static final int VARC_INT_CHAT_TAB = 41;
	static final Pattern COLLECTION_LOG_REGEX = Pattern.compile(".* received a new collection log item: (.*) \\(\\d+/\\d+\\)");
	static final Pattern RAID_LOOT_REGEX = Pattern.compile(".* received special loot from a raid: (?:[\\d,]* x )*(.+?)(?: \\((?:[\\d,]+ coins|very valuable)\\)(?: .+)*)*\\.");
	static final Pattern DROP_REGEX = Pattern.compile(".* received a drop: (?:[\\d,]* x )*(.+?)(?: \\([\\d,]+ coins\\)(?: .+)*)*\\.");
	static final Pattern CLUE_REGEX = Pattern.compile(".* received a clue item: (?:[\\d,]* x )*(.+?)(?: \\([\\d,]+ coins\\))*\\.");
	static final List<String> FINAL_OPTS = Arrays.asList("Examine", "Lock-slot", "Unlock-slot");

	@Override
	protected void startUp() throws Exception
	{
		Filepath dir = getPluginDirectory();
		dir.createDirectories();
		dataProvider.init(dir); // async

		atlasPanel = injector.getInstance(AtlasPanel.class);
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Item Atlas")
			.icon(icon)
			.priority(5)
			.panel(atlasPanel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		atlasPanel = null;
		clientToolbar.removeNavigation(navButton);
		cleanUpWidgets();
	}

	@Subscribe
	public void onMenuEntryAdded(final MenuEntryAdded event)
	{
		final Menu menu = client.getMenu();
		final MenuEntry entry = event.getMenuEntry();
		final Widget w = entry.getWidget();

		if (w == null) return;

		final int group = WidgetUtil.componentToInterface(w.getId());

		boolean shouldAddInv = (group == InterfaceID.INVENTORY
			|| group == InterfaceID.EQUIPMENT_SIDE
			|| group == InterfaceID.BANKSIDE
			|| group == InterfaceID.SHARED_BANK_SIDE)
			&& config.invLookupMode() != MenuLookupMode.DISABLED
			&& !(config.invLookupMode() == MenuLookupMode.SHIFT && !client.isKeyPressed(KeyCode.KC_SHIFT));

		boolean shouldAddEquip = (group == InterfaceID.WORNITEMS
			|| group == InterfaceID.EQUIPMENT
			|| (group == InterfaceID.BANKMAIN && w.getParentId() == InterfaceID.Bankmain.WORNITEMS_CONTAINER))
			&& config.equipLookupMode() != MenuLookupMode.DISABLED
			&& !(config.equipLookupMode() == MenuLookupMode.SHIFT && !client.isKeyPressed(KeyCode.KC_SHIFT));

		boolean shouldAddBank = ((group == InterfaceID.BANKMAIN	&& w.getParentId() == InterfaceID.Bankmain.ITEMS)
			|| group == InterfaceID.SHARED_BANK)
			&& config.bankLookupMode() != MenuLookupMode.DISABLED
			&& !(config.bankLookupMode() == MenuLookupMode.SHIFT && !client.isKeyPressed(KeyCode.KC_SHIFT));

		boolean shouldAddClog = (group == InterfaceID.COLLECTION && w.getParentId() == InterfaceID.Collection.ITEMS_CONTENTS) // Don't show on search
			&& config.clogLookupMode() != MenuLookupMode.DISABLED
			&& !(config.clogLookupMode() == MenuLookupMode.SHIFT && !client.isKeyPressed(KeyCode.KC_SHIFT));

		if (((shouldAddInv || shouldAddEquip || shouldAddBank)
			&& FINAL_OPTS.contains(entry.getOption()))
			|| (shouldAddClog && "Check".equals(entry.getOption()) && entry.getIdentifier() == 1))
		{
			int itemId = w.getItemId();
			if (shouldAddEquip) {
				final Widget widgetItem = w.getChild(1);
				if (widgetItem != null) {
					itemId = widgetItem.getItemId();
				}
			}

			// Handle items with different IDs in the log than in inventories
			if (shouldAddClog) {
				final EnumComposition itemMapEnum = client.getEnum(3721);
				int[] keys = itemMapEnum.getKeys();
				int[] values = itemMapEnum.getIntVals();
				for (int i = 0; i < values.length; i++){
					if (values[i] == itemId) {
						itemId = keys[i];
					}
				}

				if (ITEM_ID_MAP.containsKey(itemId)) {
					itemId = ITEM_ID_MAP.get(itemId);
				}
			}

			int finalItemId = itemId;
			menu.createMenuEntry(-1)
				.setOption("Atlas Lookup")
				.setTarget(entry.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(e ->
				{
					atlasPanel.displayItemById(finalItemId);
					SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navButton));
				});
		}
	}

	@Subscribe
	public void onPluginMessage(PluginMessage event) {
		// "notenoughrunes" kept so Quest Helper's existing integration still reaches us
		if (!event.getNamespace().equals("itematlas") && !event.getNamespace().equals("notenoughrunes")) {
			return;
		}

		Map<String, Object> data = event.getData();

		if (event.getName().equals("displayItemById")) {
			Object itemId = data.getOrDefault("itemId", null);

			if (itemId instanceof Integer) {
				if (data.get("openUses") instanceof Boolean) {
					atlasPanel.displayItemById((int) itemId, (boolean) data.get("openUses"));
				} else {
					atlasPanel.displayItemById((int) itemId);
				}

				SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navButton));
			} else {
				log.error("Invalid type sent to displayItemById event, expected Integer");
			}
		}
		else if (event.getName().equals("searchItemName")) {
			Object itemName = data.getOrDefault("itemName", null);

			if (itemName instanceof String) {
				atlasPanel.searchItemName((String) itemName);
				SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navButton));
			} else {
				log.error("Invalid type sent to searchItemName event, expected String");
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (itemOwnership.onContainerChanged(event.getContainerId(), event.getItemContainer()))
		{
			AtlasDropsPanel.refreshNeeds(itemOwnership);
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == SCRIPT_REBUILD_CHATBOX && config.ccBroadcastLookup())
		{
			matchMessages();
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event) {
		if (event.getCommand().equals("nerlookup")) {
			var itemId = event.getArguments()[0];
			atlasPanel.displayItemById(Integer.parseInt(itemId));
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (event.getGroup().equals("itematlas")) {
			if (event.getKey().equals("showMembersStar"))
			{
				SwingUtilities.invokeLater(atlasPanel::redisplayItem);
			}
			if (config.ccBroadcastLookup())
			{
				clientThread.invoke(this::matchMessages);
			}
			else
			{
				clientThread.invoke(this::cleanUpWidgets);
			}
		}
	}

	private void matchMessages()
	{
		Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		int selectedChatTab = client.getVarcIntValue(VARC_INT_CHAT_TAB);

		if (chatbox != null && selectedChatTab != 1337) // 1337 = closed
		{
			Widget[] chatWidgets = chatbox.getDynamicChildren();

			for (int i = 1; i < chatWidgets.length; i = i + 4)
			{
				Widget messageWidget = chatWidgets[i];

				// clean widgets first
				removeChatMenuEntry(messageWidget);

//				if (messageWidgetIndex == 1 && messageWidget.getText().contains("To talk in your clan's channel"))
//				{
//					addChatMenuEntry(messageWidget, "test");
//				}

				if (messageWidget.isHidden())
				{
					continue;
				}

				String message = Text.removeTags(messageWidget.getText());

				Matcher collMatcher = COLLECTION_LOG_REGEX.matcher(message);
				if (collMatcher.find())
				{
					String item = collMatcher.group(1);
//					log.info("matched collection log: {}", item);
					addChatMenuEntry(messageWidget, item);
					continue;
				}

				Matcher raidMatcher = RAID_LOOT_REGEX.matcher(message);
				if (raidMatcher.find())
				{
					String item = raidMatcher.group(1);
//					log.info("matched raid drop: {}", item);
					addChatMenuEntry(messageWidget, item);
					continue;
				}

				Matcher dropMatcher = DROP_REGEX.matcher(message);
				if (dropMatcher.find())
				{
					String item = dropMatcher.group(1);
//					log.info("matched loot drop: {}", item);
					addChatMenuEntry(messageWidget, item);
					continue;
				}

				Matcher clueMatcher = CLUE_REGEX.matcher(message);
				if (clueMatcher.find())
				{
					String item = clueMatcher.group(1);
//					log.info("matched clue item: {}", item);
					addChatMenuEntry(messageWidget, item);
				}

			}

		}
	}

	private void cleanUpWidgets()
	{
		Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		int selectedChatTab = client.getVarcIntValue(VARC_INT_CHAT_TAB);

		if (chatbox != null && selectedChatTab != 1337) // 1337 = closed
		{
			Widget[] chatWidgets = chatbox.getDynamicChildren();

			for (int i = 1; i < chatWidgets.length; i = i + 4)
			{
				Widget messageWidget = chatWidgets[i];

				// clean widgets first
				removeChatMenuEntry(messageWidget);
			}
		}
	}


	private void addChatMenuEntry(Widget messageWidget, String itemName)
	{
		messageWidget.setAction(7, "Atlas Lookup");
		messageWidget.setHasListener(true);
		messageWidget.setOnOpListener((JavaScriptCallback) (event) -> {
			atlasPanel.searchItemNameAndDisplay(itemName);
			SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navButton));
		});
		messageWidget.setName(itemName);
	}

	private void removeChatMenuEntry(Widget messageWidget)
	{
		messageWidget.setName("");
		if (messageWidget.hasListener())
		{
			Object[] listeners = messageWidget.getOnOpListener();

			if (listeners != null)
			{
				listeners = Arrays.stream(listeners)
					.filter(listener -> !String.valueOf(listener).contains("com.itematlas.ItemAtlasPlugin"))
					.toArray();
			}

			if (listeners != null && listeners.length > 0)
			{
				messageWidget.setOnOpListener(listeners);
			}
			else
			{
				messageWidget.setOnOpListener((Object[]) null);
				messageWidget.setHasListener(false);
			}
		}
	}


	@Provides
	ItemAtlasConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ItemAtlasConfig.class);
	}
}

package com.itematlas;

import com.itematlas.types.AtlasSourceLocation;
import java.util.Arrays;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Where the player keeps an item, for sources that need one (a chest's key). The bank and group storage
 * are only sent while open, so their contents are saved to the RuneScape profile and survive restarts.
 * Everything here runs on the client thread.
 */
@Singleton
public class ItemOwnership
{
	private static final String BANK_KEY = "bankItems";
	private static final String GROUP_STORAGE_KEY = "groupStorageItems";

	@RequiredArgsConstructor
	public enum Status
	{
		CARRIED("you have it"),
		BANK("in bank"),
		GROUP_STORAGE("in group storage"),
		MISSING("not owned"),
		UNKNOWN("bank not checked yet"),
		GROUP_UNKNOWN("group storage not checked yet");

		public final String text;
	}

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	/**
	 * Saves the bank and group storage; returns whether the change can alter a {@link #status}.
	 */
	boolean onContainerChanged(int containerId, ItemContainer container)
	{
		if (containerId == InventoryID.INV || containerId == InventoryID.WORN)
		{
			return true;
		}
		String key = containerId == InventoryID.BANK ? BANK_KEY : containerId == InventoryID.INV_GROUP_TEMP ? GROUP_STORAGE_KEY : null;
		if (key == null)
		{
			return false;
		}
		// placeholders have quantity 0 and would canonicalize to the real item
		String ids = Arrays.stream(container.getItems())
			.filter(item -> item.getId() > 0 && item.getQuantity() > 0)
			.map(item -> String.valueOf(itemManager.canonicalize(item.getId())))
			.distinct()
			.collect(Collectors.joining(","));
		configManager.setRSProfileConfiguration(ItemAtlasConfig.GROUP, key, ids);
		return true;
	}

	public Status status(int itemId)
	{
		return status(carries(InventoryID.INV, itemId) || carries(InventoryID.WORN, itemId),
			configManager.getRSProfileConfiguration(ItemAtlasConfig.GROUP, BANK_KEY),
			configManager.getRSProfileConfiguration(ItemAtlasConfig.GROUP, GROUP_STORAGE_KEY),
			// 4-6: group, hardcore group and unranked group ironman
			client.getVarbitValue(VarbitID.IRONMAN) >= 4,
			itemId);
	}

	/**
	 * {@code bank} and {@code groupStorage} are the saved snapshots, null when never opened.
	 */
	static Status status(boolean carried, String bank, String groupStorage, boolean groupIronman, int itemId)
	{
		if (carried)
		{
			return Status.CARRIED;
		}
		if (stored(bank, itemId))
		{
			return Status.BANK;
		}
		if (stored(groupStorage, itemId))
		{
			return Status.GROUP_STORAGE;
		}
		if (bank == null)
		{
			return Status.UNKNOWN;
		}
		return groupIronman && groupStorage == null ? Status.GROUP_UNKNOWN : Status.MISSING;
	}

	/**
	 * Whether a location can be looted: true unless it needs an item the player is known not to own,
	 * or a quest or skill level they don't have.
	 */
	public boolean canLoot(AtlasSourceLocation location)
	{
		return (location.getRequiredItemId() <= 0 || status(location.getRequiredItemId()) != Status.MISSING)
			&& unmetRequirements(location).isEmpty();
	}

	public List<String> unmetRequirements(AtlasSourceLocation location)
	{
		return LocationRequirements.unmet(client, location.getRequirements());
	}

	/**
	 * The route plugin's header label for these locations; when any needs an item, it names it
	 * and says so in chat too, since Shortest Path shows no label.
	 */
	public String routeLabel(Collection<AtlasSourceLocation> locations, boolean otherTargets)
	{
		String needs = routeNeeds(locations, otherTargets);
		if (needs.isEmpty())
		{
			return "Item Atlas";
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Item Atlas: this route " + needs + ".", null);
		return "Item Atlas · " + needs;
	}

	/**
	 * "may need Muddy key (in bank)", or empty when none of these locations needs an item.
	 * {@code otherTargets}: the route also goes to targets that are not these locations (shops, ground spawns).
	 */
	public String routeNeeds(Collection<AtlasSourceLocation> locations, boolean otherTargets)
	{
		Map<String, Status> needs = new LinkedHashMap<>();
		for (AtlasSourceLocation location : locations)
		{
			if (location.getRequiredItem() != null)
			{
				needs.put(location.getRequiredItem(), location.getRequiredItemId() > 0 ? status(location.getRequiredItemId()) : Status.UNKNOWN);
			}
		}
		if (needs.isEmpty())
		{
			return "";
		}

		String note = needs.entrySet().stream()
			.map(need -> need.getKey() + " (" + need.getValue().text + ")")
			.collect(Collectors.joining(", "));
		// several targets: the route plugin picks the nearest, which may not be the one with the lock
		String verb = !otherTargets && locations.stream().allMatch(location -> location.getRequiredItem() != null) ? "needs " : "may need ";
		return verb + note;
	}

	private boolean carries(int containerId, int itemId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		return container != null && Arrays.stream(container.getItems())
			.mapToInt(Item::getId)
			.anyMatch(id -> id > 0 && itemManager.canonicalize(id) == itemId);
	}

	private static boolean stored(String ids, int itemId)
	{
		return ids != null && !ids.isEmpty() && Arrays.asList(ids.split(",")).contains(String.valueOf(itemId));
	}
}

package com.itematlas;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * A location's access requirements as the scraper writes them, one per line: "quest:Dragon Slayer II",
 * "started:Legends' Quest" (partial completion), "skill:Agility:70" and "note:Requires a Slayer task."
 * Checks run on the client thread; anything that can't be checked (logged out, a diary, an unknown
 * quest) counts as met, so it never blocks a route.
 */
public final class LocationRequirements
{
	// "Recipe for Disaster: Sir Amik Varze" on the wiki is "Recipe for Disaster - Sir Amik Varze" in RuneLite
	private static final Map<String, Quest> QUESTS = Arrays.stream(Quest.values())
		.collect(Collectors.toMap(quest -> normalize(quest.getName()), Function.identity(), (a, b) -> a));

	private LocationRequirements()
	{
	}

	/**
	 * What the player doesn't meet, e.g. "70 Agility (you have 65)" or "Dragon Slayer II".
	 */
	public static List<String> unmet(Client client, String requirements)
	{
		List<String> unmet = new ArrayList<>();
		if (requirements == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return unmet;
		}
		for (String line : requirements.split("\n"))
		{
			String[] parts = line.split(":", 2);
			if (parts.length < 2)
			{
				continue;
			}
			if (parts[0].equals("skill"))
			{
				String[] skillLevel = parts[1].split(":");
				Skill skill = skill(skillLevel[0]);
				if (skill == null)
				{
					continue;
				}
				// a boost reaches a requirement too
				int level = Math.max(client.getRealSkillLevel(skill), client.getBoostedSkillLevel(skill));
				if (level < Integer.parseInt(skillLevel[1]))
				{
					unmet.add(skillLevel[1] + " " + skillLevel[0] + " (you have " + level + ")");
				}
			}
			else if (parts[0].equals("quest") || parts[0].equals("started"))
			{
				Quest quest = QUESTS.get(normalize(parts[1]));
				QuestState state = quest == null ? null : quest.getState(client);
				if (state == QuestState.NOT_STARTED || (parts[0].equals("quest") && state == QuestState.IN_PROGRESS))
				{
					unmet.add(parts[0].equals("quest") ? parts[1] : "start " + parts[1]);
				}
			}
		}
		return unmet;
	}

	/**
	 * The wiki's notes, for showing as-is.
	 */
	public static List<String> notes(String requirements)
	{
		return requirements == null ? List.of() : Arrays.stream(requirements.split("\n"))
			.filter(line -> line.startsWith("note:"))
			.map(line -> line.substring("note:".length()))
			.collect(Collectors.toList());
	}

	private static Skill skill(String name)
	{
		try
		{
			return Skill.valueOf(name.toUpperCase());
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static String normalize(String name)
	{
		return name.toLowerCase().replaceAll("[^a-z0-9]", "");
	}
}

