import java.util.*;

public class NaturalOrderComparator implements Comparator<Object>
{
	int compareRight(String a, String b)
	{
		int bias = 0, ia = 0, ib = 0;

		// The longest run of digits wins. That aside, the greatest
		// value wins, but we can't know that it will until we've scanned
		// both numbers to know that they have the same magnitude, so we
		// remember it in BIAS.
		for (;; ia++, ib++)
		{
			char ca = charAt(a, ia);
			char cb = charAt(b, ib);

			if (!isDigit(ca) && !isDigit(cb)) {
				return bias;
			}
			if (!isDigit(ca)) {
				return -1;
			}
			if (!isDigit(cb)) {
				return +1;
			}
			if (ca == 0 && cb == 0) {
				return bias;
			}

			if (bias == 0) {
				if (ca < cb) {
					bias = -1;
				} else if (ca > cb) {
					bias = +1;
				}
			}
		}
	}

	public int compare(Object o1, Object o2)
	{
		String a = o1.toString();
		String b = o2.toString();

		int ia = 0, ib = 0;
		int nza = 0, nzb = 0;
		char ca, cb;

		while (true) {
			// Only count the number of zeroes leading the last number compared
			nza = nzb = 0;

			ca = charAt(a, ia);
			cb = charAt(b, ib);

			// skip over leading spaces or zeros
			while (Character.isSpaceChar(ca) || ca == '0') {
				if (ca == '0') {
					nza++;
				} else {
					// Only count consecutive zeroes
					nza = 0;
				}

				ca = charAt(a, ++ia);
			}

			while (Character.isSpaceChar(cb) || cb == '0') {
				if (cb == '0') {
					nzb++;
				} else {
					// Only count consecutive zeroes
					nzb = 0;
				}

				cb = charAt(b, ++ib);
			}

			// Process run of digits
			if (Character.isDigit(ca) && Character.isDigit(cb)) {
				int bias = compareRight(a.substring(ia), b.substring(ib));
				if (bias != 0) {
					return bias;
				}
			}

			if (ca == 0 && cb == 0) {
				// The strings compare the same. Perhaps the caller
				// will want to call strcmp to break the tie.
				return compareEqual(a, b, nza, nzb);
			}
			if (ca < cb) {
				return -1;
			}
			if (ca > cb) {
				return +1;
			}

			++ia;
			++ib;
		}
	}

	static boolean isDigit(char c) {
		return Character.isDigit(c) || c == '.' || c == ',';
	}

	static char charAt(String s, int i) {
		return i >= s.length() ? 0 : s.charAt(i);
	}

	static int compareEqual(String a, String b, int nza, int nzb) {
		if (nza - nzb != 0)
			return nza - nzb;

		if (a.length() == b.length())
			return a.compareTo(b);

		return a.length() - b.length();
	}
}

package com.itematlas;

import com.google.common.collect.ImmutableMap;
import com.itematlas.types.AtlasDropSource;
import java.util.Map;
import lombok.experimental.UtilityClass;

@UtilityClass
public class RarityParser
{

	private final Map<String, Double> PRESET_RARITY_NAMES = ImmutableMap.<String, Double>builder()
		.put("Always", 1D)
		.put("Common", 1 / 16D)
		.put("Uncommon", 1 / 64D)
		.put("Rare", 1 / 256D)
		.put("Very rare", 1 / 1024D)
		.put("Random", 1 / 4096D)
		.put("Varies", 1 / 4096D)
		.build();

	public double calculateRarity(AtlasDropSource dropSource)
	{
		return calculateRarity(dropSource.getRarity());
	}

	public double calculateRarity(String rarityString)
	{
		if (PRESET_RARITY_NAMES.containsKey(rarityString))
		{
			return PRESET_RARITY_NAMES.get(rarityString);
		}

		try
		{
			String[] fractionComponents = rarityString.split("/");
			return Double.parseDouble(fractionComponents[0].trim().replace(",","")) / Double.parseDouble(fractionComponents[1].trim().replace(",",""));
		}
		catch (NumberFormatException | ArithmeticException | ArrayIndexOutOfBoundsException e)
		{
			return 1 / 65536D;
		}
	}

}

