package com.itematlas.db;

import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.RequiredArgsConstructor;

/**
 * The wiki tables from data.json.gz, held in memory.
 * The file is {"TABLE": {"columns": [...], "rows": [[...], ...]}}, rows in ID order.
 */
@RequiredArgsConstructor
public class AtlasData
{

	private final Map<String, List<Row>> tables;

	public List<Row> table(String name)
	{
		return tables.getOrDefault(name, Collections.emptyList());
	}

	// rows are in ID order
	public Row byId(String table, int id)
	{
		List<Row> rows = table(table);
		int lo = 0;
		int hi = rows.size() - 1;
		while (lo <= hi)
		{
			int mid = (lo + hi) >>> 1;
			int midId = rows.get(mid).integer("ID");
			if (midId < id)
			{
				lo = mid + 1;
			}
			else if (midId > id)
			{
				hi = mid - 1;
			}
			else
			{
				return rows.get(mid);
			}
		}
		return null;
	}

	public static AtlasData read(Reader in) throws IOException
	{
		Map<String, List<Row>> tables = new HashMap<>();
		// the same sources, rarities and locations repeat thousands of times
		Map<String, String> strings = new HashMap<>();
		JsonReader json = new JsonReader(in);
		json.beginObject();
		while (json.hasNext())
		{
			String table = json.nextName();
			Map<String, Integer> columns = new HashMap<>();
			List<Row> rows = new ArrayList<>();
			json.beginObject();
			while (json.hasNext())
			{
				boolean isColumns = json.nextName().equals("columns");
				json.beginArray();
				while (json.hasNext())
				{
					if (isColumns)
					{
						columns.put(json.nextString(), columns.size());
						continue;
					}

					List<Object> values = new ArrayList<>(columns.size());
					json.beginArray();
					while (json.hasNext())
					{
						values.add(readValue(json, strings));
					}
					json.endArray();
					rows.add(new Row(columns, values.toArray()));
				}
				json.endArray();
			}
			json.endObject();
			tables.put(table, rows);
		}
		json.endObject();
		return new AtlasData(tables);
	}

	private static Object readValue(JsonReader json, Map<String, String> strings) throws IOException
	{
		JsonToken token = json.peek();
		if (token == JsonToken.NULL)
		{
			json.nextNull();
			return null;
		}
		if (token == JsonToken.NUMBER)
		{
			double d = json.nextDouble();
			return d == (int) d ? (Object) (int) d : (Object) d;
		}
		String s = json.nextString();
		String seen = strings.putIfAbsent(s, s);
		return seen == null ? s : seen;
	}

	@RequiredArgsConstructor
	public static class Row
	{
		private final Map<String, Integer> columns;
		private final Object[] values;

		private Object get(String column)
		{
			return values[columns.get(column)];
		}

		public String str(String column)
		{
			Object v = get(column);
			return v == null ? null : v.toString();
		}

		public int integer(String column)
		{
			Object v = get(column);
			return v instanceof Number ? ((Number) v).intValue() : 0;
		}

		public boolean bool(String column)
		{
			return integer(column) != 0;
		}
	}

}

package com.itematlas.db;

import com.google.common.base.Stopwatch;
import com.itematlas.db.queries.ModeledQuery;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.zip.GZIPInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Slf4j
public class H2DataProvider
{

	private static final ExecutorService DB_THREAD = Executors.newSingleThreadExecutor();

	private final H2DbFetcher dbFetcher;

	private volatile AtlasData data;

	public void init(Filepath dir)
	{
		dbFetcher.fetch(dir, file ->
			DB_THREAD.submit(() ->
			{
				Stopwatch sw = Stopwatch.createStarted();
				try (Reader in = new InputStreamReader(new GZIPInputStream(file.openInputStream()), StandardCharsets.UTF_8))
				{
					data = AtlasData.read(in);
					log.debug("Loaded {} in {}ms", file, sw.elapsed(TimeUnit.MILLISECONDS));
				}
				catch (Exception e)
				{
					log.error("Failed to load the data file", e);
				}
			}));
	}

	public <T> void executeSingle(ModeledQuery<T> query, Consumer<T> callback)
	{
		executeMany(query, res ->
			callback.accept(res.isEmpty() ? null : res.get(0)));
	}

	public <T> void executeMany(ModeledQuery<T> query, Consumer<List<T>> callback)
	{
		AtlasData data = this.data;
		if (data == null)
		{
			callback.accept(Collections.emptyList());
			return;
		}

		DB_THREAD.submit(() ->
		{
			Stopwatch sw = Stopwatch.createStarted();
			List<T> res;
			try
			{
				res = query.run(data);
			}
			catch (Exception e)
			{
				log.warn("Query failed in executeMany", e);
				res = Collections.emptyList();
			}
			log.debug("[{}μs] Query {}", sw.elapsed(TimeUnit.MICROSECONDS), query.getClass().getSimpleName());
			callback.accept(res);
		});
	}

}

package com.itematlas.db;

import com.google.common.hash.Hashing;
import java.io.IOException;
import java.io.InputStream;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Slf4j
public class H2DbFetcher
{

	private static final String dbFileName = "data.json.gz";
	private static final String remoteUrl = "https://raw.githubusercontent.com/Ku-Tadao/runelite-wiki-scraper/wiki-data/output/" + dbFileName;

	private final OkHttpClient httpClient;

	// calls back with the data file once it matches the remote checksum, or with the old file when offline
	public void fetch(Filepath dir, Consumer<Filepath> callback)
	{
		Filepath dbFile = dir.join(dbFileName);
		httpClient.newCall(get(remoteUrl + ".sha256")).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to download remote checksum for data file", e);
				if (dbFile.exists())
				{
					callback.accept(dbFile);
				}
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				String checksum;
				try (response)
				{
					checksum = response.body().string().trim();
				}

				if (dbFile.exists() && checksum.equals(sha256(dbFile)))
				{
					callback.accept(dbFile);
				}
				else
				{
					log.debug("Missing data file or checksum mismatch. Downloading it");
					download(dbFile, callback);
				}
			}
		});
	}

	private void download(Filepath dbFile, Consumer<Filepath> callback)
	{
		httpClient.newCall(get(remoteUrl)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Failed to download remote data file", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (!response.isSuccessful())
					{
						log.error("Failed to download remote data file: HTTP {}", response.code());
						return;
					}
					dbFile.write(response.body().bytes());
				}
				callback.accept(dbFile);
			}
		});
	}

	private static Request get(String url)
	{
		return new Request.Builder().get().url(url).build();
	}

	private static String sha256(Filepath file) throws IOException
	{
		try (InputStream is = file.openInputStream())
		{
			return Hashing.sha256().hashBytes(is.readAllBytes()).toString();
		}
	}

}

package com.itematlas.db.queries;

import com.itematlas.db.AtlasData;
import com.itematlas.types.AtlasSourceLocation;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class DropSourceLocationsQuery extends ModeledQuery<AtlasSourceLocation>
{

	private final int itemId;

	@Override
	public List<AtlasSourceLocation> run(AtlasData data)
	{
		Set<String> sources = new HashSet<>();
		for (AtlasData.Row drop : data.table("DROP_SOURCES"))
		{
			if (drop.integer("ITEM_ID") == itemId)
			{
				sources.add(drop.str("SOURCE"));
			}
		}

		List<AtlasSourceLocation> res = new ArrayList<>();
		for (AtlasData.Row location : data.table("SOURCE_LOCATIONS"))
		{
			if (sources.contains(location.str("SOURCE")))
			{
				String requiredItem = location.str("REQUIRED_ITEM");
				res.add(new AtlasSourceLocation(
					location.str("SOURCE"),
					location.str("LOCATION"),
					location.bool("IS_MEMBERS"),
					location.str("TILES"),
					requiredItem,
					requiredItem == null ? 0 : requiredItemId(data, requiredItem),
					location.str("REQUIREMENTS")
				));
			}
		}
		return res;
	}

	// the wiki can link the singular of a plural item: "house key" is the item "House keys"
	private static int requiredItemId(AtlasData data, String name)
	{
		for (AtlasData.Row item : data.table("ITEMS"))
		{
			String itemName = item.str("NAME");
			if (itemName.equals(name) || itemName.equals(name + "s"))
			{
				return item.integer("ID");
			}
		}
		return 0;
	}
}

package com.itematlas.db.queries;

import com.itematlas.db.AtlasData;
import com.itematlas.types.AtlasInfoItem;
import java.util.Collections;
import java.util.List;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class ItemByIDQuery extends ModeledQuery<AtlasInfoItem>
{

	private final int itemID;

	@Override
	public List<AtlasInfoItem> run(AtlasData data)
	{
		AtlasData.Row item = data.byId("ITEMS", itemID);
		return item == null ? Collections.emptyList() : List.of(toItem(data, item));
	}

	static AtlasInfoItem toItem(AtlasData data, AtlasData.Row item)
	{
		AtlasData.Row group = data.byId("ITEM_GROUPS", item.integer("GROUP_ID"));
		return new AtlasInfoItem(
			item.integer("ID"),
			item.str("NAME"),
			item.str("EXAMINE_TEXT"),
			group == null ? null : group.str("NAME"),
			item.str("VERSION"),
			item.str("URL"),
			item.bool("IS_MEMBERS"),
			item.bool("IS_TRADEABLE"),
			item.bool("IS_DEFAULT_VERSION")
		);
	}
}

package com.itematlas.db.queries;

import com.itematlas.db.AtlasData;
import com.itematlas.types.AtlasInfoItem;
import java.util.Collections;
import java.util.List;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class ItemByNameQuery extends ModeledQuery<AtlasInfoItem>
{

	private final String name;

	@Override
	public List<AtlasInfoItem> run(AtlasData data)
	{
		// the default version first, then the lowest ID
		AtlasData.Row best = null;
		for (AtlasData.Row item : data.table("ITEMS"))
		{
			if (item.str("NAME").equalsIgnoreCase(name)
				&& (best == null || item.bool("IS_DEFAULT_VERSION") && !best.bool("IS_DEFAULT_VERSION")))
			{
				best = item;
			}
		}
		return best == null ? Collections.emptyList() : List.of(ItemByIDQuery.toItem(data, best));
	}
}

