package com.itematlas.db.queries;

import com.itematlas.db.AtlasData;
import com.itematlas.types.AtlasProductionMaterial;
import com.itematlas.types.AtlasProductionRecipe;
import com.itematlas.types.AtlasProductionSkill;
import java.util.ArrayList;
import java.util.List;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class ItemProducedByQuery extends ModeledQuery<AtlasProductionRecipe>
{

	private final int itemID;

	@Override
	public List<AtlasProductionRecipe> run(AtlasData data)
	{
		List<AtlasProductionRecipe> res = new ArrayList<>();
		for (AtlasData.Row recipe : data.table("PRODUCTION_RECIPES"))
		{
			if (recipe.integer("OUTPUT_ITEM_ID") == itemID)
			{
				res.add(toRecipe(data, recipe));
				if (res.size() == 100)
				{
					break;
				}
			}
		}
		return res;
	}

	static AtlasProductionRecipe toRecipe(AtlasData data, AtlasData.Row recipe)
	{
		int id = recipe.integer("ID");
		AtlasProductionRecipe res = new AtlasProductionRecipe(
			recipe.str("TICKS"),
			new ArrayList<>(),
			recipe.str("FACILITIES"),
			recipe.str("TOOLS"),
			new ArrayList<>(),
			recipe.bool("IS_MEMBERS"),
			recipe.str("OUTPUT_ITEM_NAME"),
			recipe.str("OUTPUT_ITEM_VERSION"),
			recipe.integer("OUTPUT_ITEM_ID"),
			recipe.str("OUTPUT_QUANTITY"),
			recipe.str("OUTPUT_QUANTITY_NOTE"),
			recipe.str("OUTPUT_SUBTEXT")
		);

		for (AtlasData.Row m : data.table("PRODUCTION_MATERIALS"))
		{
			if (m.integer("RECIPE_ID") != id)
			{
				continue;
			}
			AtlasProductionMaterial material = new AtlasProductionMaterial(
				m.str("ITEM_NAME"),
				m.str("ITEM_VERSION"),
				m.integer("ITEM_ID"),
				m.str("QUANTITY")
			);
			if (!res.getMaterials().contains(material))
			{
				res.getMaterials().add(material);
			}
		}

		for (AtlasData.Row s : skills(data, id))
		{
			AtlasProductionSkill skill = new AtlasProductionSkill(
				s.str("NAME"),
				s.str("LEVEL"),
				s.str("EXPERIENCE"),
				s.bool("IS_BOOSTABLE")
			);
			if (!res.getSkills().contains(skill))
			{
				res.getSkills().add(skill);
			}
		}
		return res;
	}

	static List<AtlasData.Row> skills(AtlasData data, int recipeId)
	{
		List<AtlasData.Row> res = new ArrayList<>();
		for (AtlasData.Row s : data.table("PRODUCTION_SKILLS"))
		{
			if (s.integer("RECIPE_ID") == recipeId)
			{
				res.add(s);
			}
		}
		return res;
	}
}

package com.itematlas.db.queries;

import com.itematlas.db.AtlasData;
import com.itematlas.types.AtlasProductionRecipe;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class ItemProducesQuery extends ModeledQuery<AtlasProductionRecipe>
{

	private static final Pattern LEADING_INT = Pattern.compile("^\\s*([+-]?\\d+)");

	private final int itemID;
	private final String itemName;
	private final int offset;
	private final int limit;

	@Override
	public List<AtlasProductionRecipe> run(AtlasData data)
	{
		Set<Integer> usedIn = new HashSet<>();
		for (AtlasData.Row m : data.table("PRODUCTION_MATERIALS"))
		{
			if (m.integer("ITEM_ID") == itemID)
			{
				usedIn.add(m.integer("RECIPE_ID"));
			}
		}

		// TOOLS is a comma separated list of wiki names
		String tool = ", " + itemName.toLowerCase() + ", ";
		Map<AtlasData.Row, Long> level = new HashMap<>();
		List<AtlasData.Row> recipes = new ArrayList<>();
		for (AtlasData.Row recipe : data.table("PRODUCTION_RECIPES"))
		{
			String tools = recipe.str("TOOLS");
			if (usedIn.contains(recipe.integer("ID"))
				|| tools != null && (", " + tools.toLowerCase() + ", ").contains(tool))
			{
				recipes.add(recipe);
				level.put(recipe, highestLevel(data, recipe.integer("ID")));
			}
		}

		// lowest skill level first (a recipe's highest skill counts), then by output name
		recipes.sort(Comparator.<AtlasData.Row, Long>comparing(level::get, Comparator.nullsFirst(Comparator.<Long>naturalOrder()))
			.thenComparing(r -> r.str("OUTPUT_ITEM_NAME"), Comparator.nullsFirst(Comparator.<String>naturalOrder()))
			.thenComparingInt(r -> r.integer("ID")));

		List<AtlasProductionRecipe> res = new ArrayList<>();
		int end = Math.min(offset + limit, recipes.size());
		for (int i = offset; i < end; i++)
		{
			res.add(ItemProducedByQuery.toRecipe(data, recipes.get(i)));
		}
		return res;
	}

	// like SQL's MAX(CAST(LEVEL AS INTEGER)): leading digits count, others are 0, no skills is null
	private static Long highestLevel(AtlasData data, int recipeId)
	{
		Long max = null;
		for (AtlasData.Row skill : ItemProducedByQuery.skills(data, recipeId))
		{
			String text = skill.str("LEVEL");
			if (text == null)
			{
				continue;
			}
			Matcher m = LEADING_INT.matcher(text);
			long level = m.find() ? Long.parseLong(m.group(1)) : 0;
			max = max == null ? level : Math.max(max, level);
		}
		return max;
	}
}

package com.itematlas.db.queries;

import com.itematlas.db.AtlasData;
import com.itematlas.types.AtlasShop;
import com.itematlas.types.AtlasShopItem;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class ItemSoldAtQuery extends ModeledQuery<AtlasShop>
{

	private final int itemID;

	@Override
	public List<AtlasShop> run(AtlasData data)
	{
		return shopsSelling(data, shopItem -> shopItem.integer("ITEM_ID") == itemID);
	}

	// each shop holds only the matching items, not its whole stock
	static List<AtlasShop> shopsSelling(AtlasData data, Predicate<AtlasData.Row> matches)
	{
		Map<Integer, AtlasShop> shops = new LinkedHashMap<>();
		for (AtlasData.Row shopItem : data.table("SHOP_ITEMS"))
		{
			AtlasData.Row shop = data.byId("SHOPS", shopItem.integer("SHOP_ID"));
			if (shop == null || !matches.test(shopItem))
			{
				continue;
			}

			AtlasShop res = shops.computeIfAbsent(shop.integer("ID"), id -> new AtlasShop(
				shop.str("NAME"),
				shop.str("SELL_MULTIPLIER"),
				shop.str("LOCATION"),
				shop.bool("IS_MEMBERS"),
				shop.str("COORDS"),
				shop.str("TILES"),
				shop.str("PLANE"),
				shop.str("MAP_ID"),
				new ArrayList<>()
			));

			AtlasShopItem item = new AtlasShopItem(
				shopItem.str("ITEM_NAME"),
				shopItem.str("ITEM_VERSION"),
				shopItem.integer("ITEM_ID"),
				shopItem.str("CURRENCY"),
				shopItem.str("STOCK"),
				shopItem.str("BUY_PRICE"),
				shopItem.str("SELL_PRICE")
			);
			if (!res.getItems().contains(item))
			{
				res.getItems().add(item);
			}
		}
		return new ArrayList<>(shops.values());
	}
}

