		JPanel itemInfo = new JPanel();
		itemInfo.setLayout(new GridBagLayout());
		itemInfo.setBorder(new EmptyBorder(5, 5, 0, 0));

		if (versions.size() > 1) {
			versions.sort(new NaturalOrderComparator());
			String[] versionArr = versions.toArray(String[]::new);
			JPanel versionsPanel = new JPanel(new GridBagLayout());
			JComboBox<String> comboBox = new JComboBox<>(versionArr);
			comboBox.setSelectedItem(itemGroup.getSelectedVersion());
			comboBox.addItemListener(e ->
			{
				if (e.getStateChange() == ItemEvent.SELECTED)
				{
					itemGroup.setSelectedVersion((String) comboBox.getSelectedItem());
					mainPanel.displayItem(itemGroup, showingUses);
				}
			});

			versionsPanel.add(comboBox);
			itemInfo.add(versionsPanel, new GridBagConstraints(0, 0, 3, 1, 0.0, 0.0, CENTER, NONE, new Insets(0, 0, 0, 0), 4, 4));
		}

		itemInfo.add(itemIcon, new GridBagConstraints(0, 1, 1, 1, 0.0, 0.0, LINE_START, NONE, new Insets(0, 0, 0, 0), 4, 4));
		itemInfo.add(wikiIcon, new GridBagConstraints(0, 2, 1, 1, 0.0, 0.0, LINE_START, NONE, new Insets(0, 0, 0, 0), 4, 10));
		itemInfo.add(itemInfoRight, new GridBagConstraints(1, 1, 1, 2, 1.0, 0.0, LINE_END, BOTH, new Insets(0, 0, 0, 0), 4, 4));
		itemInfo.add(itemGEPriceInfo, new GridBagConstraints(0, 3, 2, 1, 0.0, 0.0, LINE_START, BOTH, new Insets(0, 20, 0, 20), 4, 4));
		itemInfo.add(itemHAPriceInfo, new GridBagConstraints(0, 4, 2, 1, 0.0, 0.0, LINE_START, BOTH, new Insets(0, 20, 0, 20), 4, 4));


		JPanel tabDisplay = new JPanel();
		MaterialTabGroup tabGroup = new MaterialTabGroup(tabDisplay);
		MaterialTab sourcesTab = new MaterialTab("Sources", tabGroup, sourcesPanel);
		MaterialTab usesTab = new MaterialTab("Uses", tabGroup, usesPanel);

		tabGroup.setBorder(new EmptyBorder(0, 0, 0, 0));
		tabGroup.addTab(sourcesTab);
		tabGroup.addTab(usesTab);
		tabGroup.select(showUses ? usesTab : sourcesTab);

		sourcesTab.setOnSelectEvent(() -> {
			showingUses = false;
			return true;
		});

		usesTab.setOnSelectEvent(() -> {
			showingUses = true;
			return true;
		});

		JPanel tabContainer = new JPanel();
		tabContainer.setLayout(new BorderLayout());
		tabContainer.add(tabGroup, BorderLayout.NORTH);
		tabContainer.add(tabDisplay, BorderLayout.CENTER);

		add(itemInfo, BorderLayout.NORTH);
		add(tabContainer, BorderLayout.CENTER);
	}

	void setItemPrices(AtlasInfoItem infoItem, JPanel geRow, JLabel geLabel, JPanel haRow, JLabel haLabel)
	{
		clientThread.invokeLater(() ->
		{
			long gePrice = itemManager.getItemPrice(infoItem.getItemID());
			ItemComposition comp = itemManager.getItemComposition(infoItem.getItemID());
			int alchable = comp.getIntValue(ITEM_COMP_ALCHABLE_PARAM);
			int haPrice = comp.getHaPrice();

			SwingUtilities.invokeLater(() ->
			{
				if (gePrice > 0)
				{
					geLabel.setText(QuantityFormatter.formatNumber(gePrice) + "gp");

					if (!infoItem.isTradeable())
					{
						geLabel.setText(geLabel.getText() + "*");
						String tooltip = "This item is not tradeable on the GE. \nDisplayed value may be based on another item this item can be transformed into.";
						addTooltip(geLabel, tooltip);
					}

					geRow.setVisible(true);
				}

				if (haPrice > 0 && alchable == 0)
				{
					haLabel.setText(QuantityFormatter.formatNumber(haPrice) + "gp");
					haRow.setVisible(true);
				}
			});
		});
	}

	private void addTooltip(JLabel toUnderline, String tooltip)
	{
		// add underline to text
		Font f = toUnderline.getFont();
		Map<TextAttribute, Object> attributes = new HashMap<>(f.getAttributes());
		attributes.put(TextAttribute.UNDERLINE, TextAttribute.UNDERLINE_LOW_DOTTED);
		toUnderline.setFont(f.deriveFont(attributes));
		toUnderline.setText(toUnderline.getText());

		// create hover tooltip
		toUnderline.setToolTipText(tooltip);
	}
}

