@Slf4j
class AtlasSearchItemPanel extends JPanel
{
	private static final Dimension ICON_SIZE = new Dimension(32, 32);

	AtlasSearchItemPanel(AtlasItemGroup itemGroup, AtlasPanel mainPanel)
	{
			log.debug("creating search item panel group: {}", itemGroup.getGroup());
			Optional<AtlasItem> searchedItemOpt = itemGroup.getItems().stream().filter((groupItem) -> Objects.equals(groupItem.getInfoItem().getVersion(), itemGroup.getSelectedVersion())).findFirst();
			AtlasItem searchedItem = searchedItemOpt.orElseGet(() -> itemGroup.getItems().get(0));
			log.debug(String.valueOf(searchedItem));
			log.debug("creating search item panel: {}", searchedItem.getInfoItem().getName());

			BorderLayout layout = new BorderLayout();
			layout.setHgap(5);
			setLayout(layout);
			setToolTipText(searchedItem.getInfoItem().getName());
			setBackground(ColorScheme.DARKER_GRAY_COLOR);

			Color background = getBackground();
			List<JPanel> panels = new ArrayList<>();
			panels.add(this);

			MouseAdapter itemPanelMouseListener = new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					for (JPanel panel : panels)
					{
						matchComponentBackground(panel, ColorScheme.DARK_GRAY_HOVER_COLOR);
					}
					setCursor(new Cursor(Cursor.HAND_CURSOR));
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					for (JPanel panel : panels)
					{
						matchComponentBackground(panel, background);
					}
					setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
				}

				@Override
				public void mouseClicked(MouseEvent e)
				{
//				log.info("Clicked " + item.getInfoItem().getName());
					mainPanel.displayItem(itemGroup);
				}

			};

			addMouseListener(itemPanelMouseListener);

			setBorder(new EmptyBorder(5, 5, 5, 0));

			JLabel itemIcon = new JLabel();
			itemIcon.setPreferredSize(ICON_SIZE);
			if (searchedItem.getIcon() != null)
			{
				searchedItem.getIcon().addTo(itemIcon);
			}
			add(itemIcon, BorderLayout.LINE_START);

			// Item details panel
			JPanel rightPanel = new JPanel(new GridLayout(1, 1));
			panels.add(rightPanel);
			rightPanel.setBackground(background);

			JLabel itemName = new JLabel();
			itemName.setForeground(Color.WHITE);
			itemName.setMaximumSize(new Dimension(0, 0));
			itemName.setPreferredSize(new Dimension(0, 0));
			itemName.setText(searchedItem.getInfoItem().getGroup());
			rightPanel.add(itemName);

			add(rightPanel, BorderLayout.CENTER);

	}

	private void matchComponentBackground(JPanel panel, Color color)
	{
		panel.setBackground(color);
		for (Component c : panel.getComponents())
		{
			c.setBackground(color);
		}
	}
}

package com.itematlas.ui;

import com.google.common.base.Strings;
import com.itematlas.db.H2DataProvider;
import com.itematlas.db.queries.ItemGroupQuery;
import com.itematlas.db.queries.SearchItemsQuery;
import com.itematlas.types.AtlasInfoItem;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.util.AsyncBufferedImage;
import org.apache.commons.text.similarity.LevenshteinDistance;

@Slf4j
class AtlasSearchResultsPanel extends JPanel
{
	private static final int MAX_RESULTS = 200;
	private static final String ERROR_PANEL = "ERROR_PANEL";
	private static final String RESULTS_PANEL = "RESULTS_PANEL";

	private final GridBagConstraints constraints = new GridBagConstraints();
	private final CardLayout cardLayout = new CardLayout();

	private final JPanel searchItemsPanel = new JPanel();
	private final JPanel centerPanel = new JPanel(cardLayout);
	private final PluginErrorPanel errorPanel = new PluginErrorPanel();

	private List<AtlasInfoItem> results = new ArrayList<>();
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final H2DataProvider dataProvider;
	private final AtlasPanel parentPanel;

	AtlasSearchResultsPanel(
		ClientThread clientThread,
		ItemManager itemManager,
		H2DataProvider dataProvider,
		AtlasPanel parentPanel
	)
	{
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.dataProvider = dataProvider;
		this.parentPanel = parentPanel;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel container = new JPanel();
		container.setLayout(new BorderLayout(5, 5));
		container.setBorder(new EmptyBorder(5, 2, 0, 2));
		container.setBackground(ColorScheme.DARK_GRAY_COLOR);

		searchItemsPanel.setLayout(new GridBagLayout());
		searchItemsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.weightx = 1;
		constraints.gridx = 0;
		constraints.gridy = 0;

		/* This panel wraps the results panel and guarantees the scrolling behaviour */
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(searchItemsPanel, BorderLayout.NORTH);

		/*  The results wrapper, this scrolling panel wraps the results container */
		JScrollPane resultsWrapper = new JScrollPane(wrapper);
		resultsWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resultsWrapper.getVerticalScrollBar().setPreferredSize(new Dimension(12, 0));
		resultsWrapper.getVerticalScrollBar().setBorder(new EmptyBorder(0, 5, 0, 0));
		resultsWrapper.setVisible(false);

		/* This panel wraps the error panel and limits its height */
		JPanel errorWrapper = new JPanel(new BorderLayout());
		errorWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		errorWrapper.add(errorPanel, BorderLayout.NORTH);

		errorPanel.setContent(
			"Item Atlas Search",
			"Here you can search an item by its name to find its sources and uses"
		);

		centerPanel.add(resultsWrapper, RESULTS_PANEL);
		centerPanel.add(errorWrapper, ERROR_PANEL);

		cardLayout.show(centerPanel, ERROR_PANEL);

		container.add(centerPanel, BorderLayout.CENTER);

		add(container, BorderLayout.CENTER);
	}

	boolean updateSearch(IconTextField searchBar)
	{
		String lookup = searchBar.getText();

		if (Strings.isNullOrEmpty(lookup))
		{
			searchItemsPanel.removeAll();
			errorPanel.setContent(
				"Item Atlas Search",
				"Here you can search an item by its name to find its sources and uses"
			);
			cardLayout.show(centerPanel, ERROR_PANEL);
			searchBar.setIcon(IconTextField.Icon.SEARCH);
			SwingUtilities.invokeLater(searchItemsPanel::updateUI);
			return false;
		}

		searchItemsPanel.removeAll();
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setEditable(false);
		searchBar.setIcon(IconTextField.Icon.LOADING);
		return true;
	}

	void itemSearch(IconTextField searchBar)
	{
		if (!updateSearch(searchBar))
		{
			return;
		}

		String search = searchBar.getText();
		results.clear();

		this.dataProvider.executeMany(new SearchItemsQuery(search), searchResults ->
			this.clientThread.invokeLater(() ->
			{
				Map<String, List<AtlasInfoItem>> groupedResults = new HashMap<>();
				searchResults.forEach((itemInfo) ->
				{
					List<AtlasInfoItem> group;
					if (groupedResults.containsKey(itemInfo.getGroup()))
					{
						group = groupedResults.get(itemInfo.getGroup());
					}
					else
					{
						group = new ArrayList<>();
						groupedResults.put(itemInfo.getGroup(), group);
					}
					group.add(itemInfo);
				});

				groupedResults.forEach((groupName, group) -> {
					group.sort(Comparator.comparing(AtlasInfoItem::getItemID));
					Optional<AtlasInfoItem> defaultItem = group.stream().filter(AtlasInfoItem::isDefaultVersion).findFirst();
					AtlasInfoItem itemResult;
					itemResult = defaultItem.orElseGet(() -> group.get(0));

					results.add(itemResult);

				});

				if (results.isEmpty())
				{
					searchBar.setIcon(IconTextField.Icon.ERROR);
					errorPanel.setContent("No results found", "No items were found with that name, please try again.");
					cardLayout.show(centerPanel, ERROR_PANEL);
					searchBar.setEditable(true);
					return;
				}

				results = results.stream()
					.sorted(compareNameAndGroup(search))
					.collect(Collectors.toList());

				SwingUtilities.invokeLater(this::processResult);
				searchBar.setIcon(IconTextField.Icon.SEARCH);
			}));
	}

	void itemSearchFirst(IconTextField searchBar)
	{
		if (!updateSearch(searchBar))
		{
			return;
		}

		String search = searchBar.getText();
		results.clear();

		this.dataProvider.executeMany(new SearchItemsQuery(search), searchResults ->
			this.clientThread.invokeLater(() ->
			{
				results.addAll(searchResults);

				if (results.isEmpty())
				{
					searchBar.setIcon(IconTextField.Icon.ERROR);
					errorPanel.setContent("No results found", "No items were found with that name, please try again.");
					cardLayout.show(centerPanel, ERROR_PANEL);
					searchBar.setEditable(true);
					return;
				}

				results = results.stream()
					.sorted(compareNameAndGroup(search))
					.collect(Collectors.toList());

				SwingUtilities.invokeLater(this::showFirstResult);
				searchBar.setIcon(IconTextField.Icon.SEARCH);
			}));
	}

	void showFirstResult()
	{
		if (results.isEmpty())
		{
			return;
		}

		AtlasInfoItem item = results.get(0);

		this.dataProvider.executeMany(new ItemGroupQuery(item.getGroup()), infoItems ->
			clientThread.invokeLater(() ->
			{
				List<AtlasItem> atlasItems = infoItems.stream().map((groupItem) -> {
					AsyncBufferedImage itemImage = this.itemManager.getImage(itemManager.canonicalize(groupItem.getItemID()));
					return new AtlasItem(itemImage, groupItem);
				}).collect(Collectors.toList());


				AtlasItemGroup itemGroup = new AtlasItemGroup(item.getGroup(), item.getVersion(), atlasItems);
				parentPanel.displayItem(itemGroup);
			})
		);
	}

	void processResult()
	{

		cardLayout.show(centerPanel, RESULTS_PANEL);
		if (results.isEmpty())
		{
//			log.info("No results found");
			return;
		}

			AtomicInteger index = new AtomicInteger();

			for (AtlasInfoItem infoItem : results)
			{
				if ((index.get() + 1) > MAX_RESULTS)
				{
					break;
				}

				this.dataProvider.executeMany(new ItemGroupQuery(infoItem.getGroup()), infoItems ->
				{
					clientThread.invokeLater(() -> {
						log.debug("processing results");

						List<AtlasItem> atlasItems = new ArrayList<>();
						infoItems.forEach((item) -> atlasItems.add(new AtlasItem(this.itemManager.getImage(itemManager.canonicalize(item.getItemID())), item)));

						AtlasItemGroup itemGroup = new AtlasItemGroup(infoItem.getGroup(), infoItem.getVersion(), atlasItems);

						SwingUtilities.invokeLater(() -> {
							log.debug("processing results in swing");

							AtlasSearchItemPanel panel = new AtlasSearchItemPanel(itemGroup, parentPanel);
							if (index.getAndIncrement() > 0)
							{
								JPanel marginWrapper = new JPanel(new BorderLayout());
								marginWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
								marginWrapper.setBorder(new EmptyBorder(5, 0, 0, 0));
								marginWrapper.add(panel, BorderLayout.NORTH);
								searchItemsPanel.add(marginWrapper, constraints);
							}
							else
							{
								searchItemsPanel.add(panel, constraints);
							}
							searchItemsPanel.updateUI();

							constraints.gridy++;
						});
					});

				});
			}


	}

	private Comparator<AtlasInfoItem> compareNameAndGroup(String itemName)
	{
		return Comparator.comparing((AtlasInfoItem item) -> new LevenshteinDistance().apply(item.getName(), itemName))
			.thenComparing(item -> new LevenshteinDistance().apply(item.getGroup(), itemName));

	}
}

package com.itematlas.ui;

import com.itematlas.ItemAtlasPlugin;
import java.awt.BorderLayout;
import java.awt.Component;
