import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

final class AtlasSourceRouteUtil
{
	static final ImageIcon MEMBERS_ICON = new ImageIcon(ImageUtil.loadImageResource(AtlasSourceRouteUtil.class, "members.png"));

	private AtlasSourceRouteUtil()
	{
	}

	/**
	 * Escapes wiki text for an HTML tooltip.
	 */
	static String html(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * Label text that wraps at {@code width} pixels instead of ending in an ellipsis.
	 */
	static String wrap(String text, int width)
	{
		return text == null ? null : "<html><div style='width:" + width + "px'>" + html(text) + "</div></html>";
	}

	/**
	 * Marks a members-only source with the star, the way the wiki does.
	 */
	static void markMembers(JLabel label)
	{
		label.setIcon(MEMBERS_ICON);
		label.setIconTextGap(4);
	}

	/**
	 * A scroll pane's view, as wide as the pane: a view that asks for more runs under the edge, as there is no sideways scrollbar.
	 */
	static JPanel scrollView()
	{
		return new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getPreferredSize()
			{
				return new Dimension(0, super.getPreferredSize().height);
			}
		};
	}

	/**
	 * A left-to-right row that wraps onto more lines within {@code width}.
	 */
	static JPanel flowPanel(int width)
	{
		return new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 1))
		{
			@Override
			public Dimension getPreferredSize()
			{
				// FlowLayout wraps but asks for one row, so lay out at the width to measure the real height
				setSize(width, Short.MAX_VALUE);
				doLayout();
				int height = 0;
				for (Component component : getComponents())
				{
					height = Math.max(height, component.getY() + component.getHeight());
				}
				return new Dimension(width, height + 1);
			}
		};
	}

	/**
	 * Sets a half-size item icon (18x16) for small-font lines, once the image has loaded.
	 */
	static void smallItemIcon(JLabel label, AsyncBufferedImage image)
	{
		image.onLoaded(() -> SwingUtilities.invokeLater(() ->
			label.setIcon(new ImageIcon(ImageUtil.resizeImage(image, 18, 16, true)))));
	}

	/**
	 * Marks a source the wiki gives no map location for, so routing skips it.
	 */
	static JLabel noLocationLabel()
	{
		JLabel label = new JLabel("No location data");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		label.setToolTipText("The wiki has no map location for this, so routing skips it.");
		return label;
	}

	/**
	 * A "+ summary" line that shows or hides the given parts when clicked. They start hidden, like loot tracker boxes.
	 */
	static JLabel collapseHeader(String summary, JComponent... parts)
	{
		JLabel header = new JLabel("+ " + summary);
		header.setFont(FontManager.getRunescapeSmallFont());
		header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.setCursor(new Cursor(Cursor.HAND_CURSOR));
		for (JComponent part : parts)
		{
			part.setVisible(false);
		}
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (!SwingUtilities.isLeftMouseButton(e))
				{
					return;
				}
				boolean show = !parts[0].isVisible();
				for (JComponent part : parts)
				{
					part.setVisible(show);
				}
				header.setText((show ? "- " : "+ ") + summary);
				header.getParent().revalidate();
				header.getParent().repaint();
			}
		});
		return header;
	}

	/**
	 * Shown in place of a tab whose item has nothing listed on the wiki.
	 */
	static JPanel noDataPanel(String text)
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBorder(new EmptyBorder(10, 10, 10, 10));
		JLabel label = new JLabel("<html><div style='text-align:center'>" + text + "</div></html>", SwingConstants.CENTER);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(label, BorderLayout.NORTH);
		return panel;
	}

	/**
	 * Plugins that accept "path" PluginMessages. GPS is checked first and gets its own namespace,
	 * because it also listens on Shortest Path's: sending there with both enabled routes twice.
	 */
	@RequiredArgsConstructor
	enum Router
	{
		GPS("GPS", "gps"),
		SHORTEST_PATH("Shortest Path", "shortestpath");

		final String pluginName;
		final String namespace;

		// route plugins read the player's position when handling this, which only works on the client thread
		void route(ClientThread clientThread, EventBus eventBus, Map<String, Object> data)
		{
			Map<String, Object> message = new HashMap<>(data);
			// GPS shows this in its route header; Shortest Path ignores it. Callers may pass their own
			message.putIfAbsent("source", "Item Atlas");
			clientThread.invoke(() -> eventBus.post(new PluginMessage(namespace, "path", message)));
		}
	}

	/**
	 * Gives the targets a right-click menu that routes to the nearest of the tiles, when a route plugin is on
	 * and the player is logged in. Call on the client thread.
	 */
	static void addRouteMenu(Client client, ClientThread clientThread, EventBus eventBus, PluginManager pluginManager, Set<WorldPoint> tiles, JComponent... targets)
	{
		Router router = findActiveRouter(pluginManager);
		if (tiles.isEmpty() || router == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		JPopupMenu menu = new JPopupMenu("Menu");
		// no "start": the route plugin then starts from where the player is when they click
		menu.add(new JMenuItem(new AbstractAction(router.pluginName)
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				router.route(clientThread, eventBus, Map.of("target", tiles));
			}
		}));

		String hint = "Right-click to route with " + router.pluginName;
		SwingUtilities.invokeLater(() ->
		{
			for (JComponent target : targets)
			{
				if (target.getToolTipText() == null)
				{
					target.setToolTipText(hint);
				}
				target.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mouseClicked(MouseEvent e)
					{
						if (SwingUtilities.isRightMouseButton(e) && e.getClickCount() == 1)
						{
							menu.show(target, e.getX(), e.getY());
						}
					}
				});
			}
		});
	}

	@Nullable
	static Router findActiveRouter(PluginManager pluginManager)
	{
		for (Router router : Router.values())
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (router.pluginName.equals(plugin.getName()) && pluginManager.isPluginActive(plugin))
				{
					return router;
				}
			}
		}
		return null;
	}

	@Nullable
	static WorldPoint parseWorldPoint(@Nullable String coords, @Nullable String plane)
	{
		if (coords == null || plane == null)
		{
			return null;
		}

		String[] parts = coords.split(",", -1);
		if (parts.length != 2)
		{
			return null;
		}

		return toWorldPoint(parts[0], parts[1], plane);
	}

	/**
	 * Parses a TILES column ("x,y,plane" separated by ';'), skipping invalid tiles.
	 */
	static List<WorldPoint> parseTiles(@Nullable String tiles)
	{
		List<WorldPoint> points = new ArrayList<>();
		if (tiles == null || tiles.isEmpty())
		{
			return points;
		}

		for (String tile : tiles.split(";"))
		{
			String[] parts = tile.split(",", -1);
			WorldPoint point = parts.length == 3 ? toWorldPoint(parts[0], parts[1], parts[2]) : null;
			if (point != null)
			{
				points.add(point);
			}
		}
		return points;
	}

	/**
	 * Every listed tile, or the single coordinate for data without tiles.
	 */
	static List<WorldPoint> tilesOrCoords(@Nullable String tileList, @Nullable String coords, @Nullable String plane)
	{
		List<WorldPoint> tiles = parseTiles(tileList);
		if (tiles.isEmpty())
		{
			WorldPoint point = parseWorldPoint(coords, plane);
			if (point != null)
			{
				tiles.add(point);
			}
		}
		return tiles;
	}

	@Nullable
	private static WorldPoint toWorldPoint(String xs, String ys, String zs)
	{
		try
		{
			int x = Integer.parseInt(xs.trim());
			int y = Integer.parseInt(ys.trim());
			int z = Integer.parseInt(zs.trim());

			// Jagex packed coordinates use 14 bits for x/y, and RuneLite defines four planes.
			return x >= 0 && x <= 0x3FFF && y >= 0 && y <= 0x3FFF && z >= 0 && z < Constants.MAX_Z
				? new WorldPoint(x, y, z)
				: null;
		}
		catch (NumberFormatException ignored)
		{
			return null;
		}
	}
}

package com.itematlas.ui;

