package com.itematlas;

import static com.itematlas.ItemOwnership.Status.BANK;
import static com.itematlas.ItemOwnership.Status.CARRIED;
import static com.itematlas.ItemOwnership.Status.GROUP_STORAGE;
import static com.itematlas.ItemOwnership.Status.GROUP_UNKNOWN;
import static com.itematlas.ItemOwnership.Status.MISSING;
import static com.itematlas.ItemOwnership.Status.UNKNOWN;
import static com.itematlas.ItemOwnership.status;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class ItemOwnershipTest
{
	private static final int MUDDY_KEY = 991;

	@Test
	public void statusOrder()
	{
		assertEquals(CARRIED, status(true, "991", "991", false, MUDDY_KEY));
		assertEquals(BANK, status(false, "995,991", "991", false, MUDDY_KEY));
		assertEquals(GROUP_STORAGE, status(false, "995", "991", false, MUDDY_KEY));
		assertEquals(MISSING, status(false, "995", null, false, MUDDY_KEY));
		// an empty bank was still seen
		assertEquals(MISSING, status(false, "", null, false, MUDDY_KEY));
		// the group storage alone doesn't say what the bank holds
		assertEquals(UNKNOWN, status(false, null, "995", false, MUDDY_KEY));
	}

	@Test
	public void groupIronmanNeedsGroupStorageSeen()
	{
		assertEquals(GROUP_UNKNOWN, status(false, "995", null, true, MUDDY_KEY));
		assertEquals(MISSING, status(false, "995", "", true, MUDDY_KEY));
		assertEquals(UNKNOWN, status(false, null, null, true, MUDDY_KEY));
	}

	@Test
	public void snapshotMatchesWholeIds()
	{
		assertEquals(MISSING, status(false, "9910,1991", null, false, MUDDY_KEY));
	}
}

package com.itematlas.db;

import com.itematlas.db.queries.DropSourceLocationsQuery;
import com.itematlas.db.queries.ItemByNameQuery;
import com.itematlas.db.queries.ItemProducesQuery;
import com.itematlas.types.AtlasProductionRecipe;
import java.io.StringReader;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class AtlasDataTest
{

	private static final String JSON = ("{"
		+ "'ITEM_GROUPS': {'columns': ['ID', 'NAME', 'SEARCH_NAME'], 'rows': [[1, 'Group', 'group']]},"
		+ "'ITEMS': {'columns': ['ID', 'NAME', 'EXAMINE_TEXT', 'GROUP_ID', 'VERSION', 'URL', 'IS_MEMBERS', 'IS_TRADEABLE', 'IS_DEFAULT_VERSION', 'SEARCH_NAME'], 'rows': ["
		+ "  [1, 'House keys', '', 1, null, '', 0, 0, 0, 'house keys'],"
		+ "  [2, 'Bar', '', 1, 'Old', '', 0, 0, 0, 'bar'],"
		+ "  [3, 'bar', '', 1, null, '', 0, 0, 1, 'bar']]},"
		+ "'DROP_SOURCES': {'columns': ['ID', 'ITEM_ID', 'SOURCE'], 'rows': [[1, 2, 'Goblin']]},"
		+ "'SOURCE_LOCATIONS': {'columns': ['ID', 'SOURCE', 'LOCATION', 'IS_MEMBERS', 'TILES', 'REQUIRED_ITEM', 'REQUIREMENTS'], 'rows': ["
		+ "  [1, 'Goblin', 'Lumbridge', 0, '', 'House key', null]]},"
		+ "'PRODUCTION_RECIPES': {'columns': ['ID', 'TICKS', 'FACILITIES', 'TOOLS', 'IS_MEMBERS', 'OUTPUT_ITEM_NAME', 'OUTPUT_ITEM_VERSION', 'OUTPUT_ITEM_ID', 'OUTPUT_QUANTITY', 'OUTPUT_QUANTITY_NOTE', 'OUTPUT_SUBTEXT'], 'rows': ["
		+ "  [1, null, null, 'Hammer, Chisel', 0, 'Zed', null, 9, '1', null, null],"
		+ "  [2, null, null, null, 0, 'Bed', null, 9, '1', null, null],"
		+ "  [3, null, null, 'Hammers', 0, 'Nope', null, 9, '1', null, null],"
		+ "  [4, null, null, null, 0, 'Axe', null, 9, '1', null, null],"
		+ "  [5, null, null, 'chisel', 0, 'Cup', null, 9, '1', null, null]]},"
		+ "'PRODUCTION_MATERIALS': {'columns': ['ID', 'RECIPE_ID', 'ITEM_NAME', 'ITEM_VERSION', 'ITEM_ID', 'QUANTITY'], 'rows': ["
		+ "  [1, 2, 'Hammer', null, 7, '1'], [2, 4, 'Hammer', null, 7, '1'], [3, 4, 'Hammer', null, 7, '1']]},"
		+ "'PRODUCTION_SKILLS': {'columns': ['ID', 'RECIPE_ID', 'NAME', 'LEVEL', 'EXPERIENCE', 'IS_BOOSTABLE'], 'rows': ["
		+ "  [1, 1, 'Smithing', '5 (boostable)', '1', 1], [2, 2, 'Crafting', '50', '1', 0], [3, 2, 'Smithing', '10', '1', 0],"
		+ "  [4, 4, 'Crafting', 'n/a', '1', 0]]}"
		+ "}").replace('\'', '"');

	@Test
	public void queriesMatchTheOldSql() throws Exception
	{
		AtlasData data = AtlasData.read(new StringReader(JSON));

		// case-insensitive, default version first
		assertEquals(3, new ItemByNameQuery("BAR").run(data).get(0).getItemID());

		// "House key" links the plural item
		assertEquals(1, new DropSourceLocationsQuery(2).run(data).get(0).getRequiredItemId());

		// used as a material or listed as a tool; lowest highest level first (unparseable is 0), duplicates merged
		List<AtlasProductionRecipe> uses = new ItemProducesQuery(7, "hammer", 0, 10).run(data);
		assertEquals(List.of("Axe", "Zed", "Bed"), uses.stream().map(AtlasProductionRecipe::getOutputItemName).collect(Collectors.toList()));
		assertEquals(1, uses.get(0).getMaterials().size());
		assertEquals(2, uses.get(2).getSkills().size());
		assertEquals(List.of("Zed"), new ItemProducesQuery(7, "hammer", 1, 1).run(data).stream()
			.map(AtlasProductionRecipe::getOutputItemName).collect(Collectors.toList()));
	}

}

package com.itematlas.ui;

import com.itematlas.types.AtlasDropSource;
import java.util.List;
import java.util.stream.Collectors;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class AtlasDropsPanelTest
{
	@Test
	public void displayName()
	{
		assertEquals("Bronze dragon (Standard)", AtlasDropsPanel.displayName("Bronze dragon#Standard"));
		assertEquals("Muddy chest", AtlasDropsPanel.displayName("Muddy chest"));
	}

	@Test
	public void levelText()
	{
		assertEquals("Lvl 50", AtlasDropsPanel.levelText("50"));
		assertEquals("Lvl 13–76", AtlasDropsPanel.levelText("24,76,13"));
		assertEquals("", AtlasDropsPanel.levelText(""));
		assertEquals("N/A", AtlasDropsPanel.levelText("N/A"));
	}

	@Test
	public void mergeBySourceSortsByBestRate()
	{
		List<List<AtlasDropSource>> merged = AtlasDropsPanel.mergeBySource(List.of(
			drop("Goblin", 14, "1/512"),
			drop("Unknown", 1, "???"),
			drop("Goblin", 1, "1/128"),
			drop("Chest", 1, "Always")));
		assertEquals(List.of("Chest", "Goblin", "Unknown"),
			merged.stream().map(drops -> drops.get(0).getSource()).collect(Collectors.toList()));
		// quantities in order within a source
		assertEquals(1, merged.get(1).get(0).getQuantityLow());
		assertEquals(14, merged.get(1).get(1).getQuantityLow());
	}

	@Test
	public void quantityText()
	{
		assertEquals("x1", AtlasDropsPanel.quantityText(List.of(drop("Goblin", 1, "1/2"))));
		assertEquals("x1 / x14", AtlasDropsPanel.quantityText(List.of(drop("Goblin", 1, "1/2"), drop("Goblin", 14, "1/4"))));
		assertEquals("x1-300", AtlasDropsPanel.quantityText(List.of(drop("Goblin", 1, "1/2"), drop("Goblin", 14, "1/4"), drop("Goblin", 300, "1/8"))));
	}

	private static AtlasDropSource drop(String source, int quantity, String rarity)
	{
		return new AtlasDropSource(source, quantity, quantity, rarity, "", "combat");
	}
}

package com.itematlas.ui;

import java.awt.BorderLayout;
import javax.swing.Box;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class AtlasSourceRouteUtilTest
{
	@Test
	public void scrollViewStaysAsWideAsItsPane()
	{
		JPanel view = AtlasSourceRouteUtil.scrollView();
		view.add(Box.createHorizontalStrut(500), BorderLayout.NORTH);
		JScrollPane pane = new JScrollPane(view);
		pane.setSize(200, 100);
		pane.doLayout();
		pane.getViewport().doLayout();
		assertEquals(pane.getViewport().getWidth(), view.getWidth());
	}

	@Test
	public void filledSectionKeepsItsHeightInAStack()
	{
		AtlasSection section = new AtlasSection("Shops", "", new java.util.HashMap<>(), true);
		section.fill(" (1)", java.util.List.of(new javax.swing.JLabel("row")));
		JPanel stack = new JPanel();
		stack.setLayout(new javax.swing.BoxLayout(stack, javax.swing.BoxLayout.Y_AXIS));
		stack.add(section);
		stack.setSize(220, 500);
		stack.doLayout();
		assertEquals(true, section.getHeight() > 0);
	}

	@Test
	public void parsesValidWorldPoints()
	{
		assertEquals(new WorldPoint(0, 16383, 0), AtlasSourceRouteUtil.parseWorldPoint("0,16383", "0"));
		assertEquals(new WorldPoint(3200, 3201, 3), AtlasSourceRouteUtil.parseWorldPoint("3200,3201", "3"));
		assertEquals(new WorldPoint(1380, 2932, 0), AtlasSourceRouteUtil.parseWorldPoint("1380, 2932", " 0 "));
	}

	@Test
	public void rejectsInvalidWorldPoints()
	{
		String[][] invalid = {
			{null, "0"},
			{"1,2", null},
			{"", "0"},
			{"1", "0"},
			{"1,2,3", "0"},
			{"-1,2", "0"},
			{"1 2,3", "0"},
			{"a,2", "0"},
			{"16384,2", "0"},
			{"999999999999,2", "0"},
			{"1,2", "-1"},
			{"1,2", "4"},
			{"1,2", "a"}
		};

		for (String[] point : invalid)
		{
			assertNull(AtlasSourceRouteUtil.parseWorldPoint(point[0], point[1]));
		}
	}
}
